INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch09$PT127-S1-Q8$batch09$, 127, 1, 8, $batch09$Principle-Conform$batch09$, $batch09$When presented with the evidence against him, Ellison freely admitted to engaging in illegal transactions using company facilities. However, the company obtained the evidence by illegally recording Ellison’s conversations. Therefore, although the company may demand that he immediately cease, it cannot justifiably take any punitive measures against him.$batch09$, $batch09$Which one of the following judgments best illustrates the principle illustrated by the argument above?$batch09$, $batch09$D$batch09$, true, $batch09$Batch 09; question text from local bank.$batch09$ FROM lr_sections s WHERE s.preptest=127 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT127-S1-Q8$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$A$batch09$, $batch09$After Price confessed to having stolen money from Long over a period of several years, Long began stealing from Price. Despite Price’s guilt, Long was not justified in taking illegal action against him.$batch09$, $batch09$Wrong Structure$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT127-S1-Q8$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$A$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$B$batch09$, $batch09$Shakila’s secretary has admitted that he is illegally receiving cable television without paying for it. Shakila would not be justified in reporting him, though, since she once did the same thing.$batch09$, $batch09$Wrong Reason$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT127-S1-Q8$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$B$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$C$batch09$, $batch09$After Takashi told Sarah’s parents that he had seen her at the movies on Tuesday, Sarah confessed to sneaking out that day. On Monday, however, Takashi had violated the local curfew for minors. Hence Sarah’s parents cannot justifiably punish her in this case.$batch09$, $batch09$Wrong Person$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT127-S1-Q8$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$C$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$D$batch09$, $batch09$After a conservation officer discovered them, Kuttner admitted that he had set the illegal animal traps on his land. But, because she was trespassing at the time, the conservation officer cannot justifiably punish Kuttner in this case.$batch09$, $batch09$Correct$batch09$, true FROM lr_questions q WHERE q.qid=$batch09$PT127-S1-Q8$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$D$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$E$batch09$, $batch09$Ramirez was forced by the discovery of new evidence to admit that she lied about her role in managing the chief of staff’s financial affairs. Nevertheless, the board of directors cannot justifiably take action against Ramirez, because in past instances it has pardoned others guilty of similar improprieties.$batch09$, $batch09$Wrong Reason$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT127-S1-Q8$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$E$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT127-S1-Q8$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$The company can demand that Ellison stop, but it can't justifiably punish Ellison.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$Ellison admitted the illegal transactions when shown the evidence. But the company got that evidence by illegally recording Ellison's conversations.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$Ellison is guilty, and the argument doesn't deny it. What blocks punishment is how the evidence came out: the party who wants to punish broke the law to uncover the wrongdoing. The principle: if you discovered someone's wrongdoing through your own illegal act, you can't justifiably punish them for it.$batch09$), (3, $batch09$Goal$batch09$, $batch09$A guilty party who can't be punished because the punisher discovered the wrongdoing illegally.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT127-S1-Q8$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Long's illegal act is the punishment, stealing back, not the way Price's theft was discovered. Price confessed. Nothing about the discovery was illegal.$batch09$), ($batch09$B$batch09$, $batch09$Shakila can't report the secretary because Shakila once did the same thing. That's hypocrisy, not evidence gathered illegally.$batch09$), ($batch09$C$batch09$, $batch09$Takashi broke curfew on Monday, but the sighting was on Tuesday, so Takashi's violation had nothing to do with discovering Sarah. And Takashi isn't the one punishing. Sarah's parents are, and they did nothing wrong.$batch09$), ($batch09$D$batch09$, $batch09$The conservation officer found Kuttner's illegal traps while trespassing on Kuttner's land, so the discovery itself was illegal. Kuttner admits it, and the officer, the one who would punish, can't justifiably do so. That matches the company and Ellison.$batch09$), ($batch09$E$batch09$, $batch09$The board can't act because it pardoned others before. That's about consistency, and the evidence against Ramirez wasn't obtained illegally.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT127-S1-Q8$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
